user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers| && forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
{
    var maxSoFar := numbers[0];
    var resultList := new int[|numbers|];

    // Initialize the result list with the first element
    resultList[0] := maxSoFar;

    // Iterate through the list to find rolling maximums
    var i := 1;
    while i < |numbers|
        invariant 0 <= i <= |numbers| && resultList[0..i] == [maxSoFar] + [Max(numbers[0..j+1]) | j := 0..i-1]
    {
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i];
        }
        resultList[i] := maxSoFar;
        i := i + 1;
    }

    result := resultList;
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

